// 128-bit unsigned product and compare, written here (no compiler 128-bit type).
struct U {
  u64 hi, lo;
};
U mul(u64 a, u64 b) {
  const u64 a0 = a & 0xFFFFFFFFu, a1 = a >> 32, b0 = b & 0xFFFFFFFFu, b1 = b >> 32;
  const u64 p00 = a0 * b0, p01 = a0 * b1, p10 = a1 * b0, p11 = a1 * b1;
  const u64 mid = (p00 >> 32) + (p01 & 0xFFFFFFFFu) + (p10 & 0xFFFFFFFFu);
  return U{p11 + (p01 >> 32) + (p10 >> 32) + (mid >> 32), (p00 & 0xFFFFFFFFu) | (mid << 32)};
}
U add(U a, U b) {
  U r{a.hi + b.hi, a.lo + b.lo};
  if (r.lo < a.lo) ++r.hi;
  return r;
}
U shl4(U a) { return U{(a.hi << 4) | (a.lo >> 60), a.lo << 4}; }
bool le(U a, U b) { return a.hi < b.hi || (a.hi == b.hi && a.lo <= b.lo); }
u64 absu(i64 v) { return v < 0 ? static_cast<u64>(0) - static_cast<u64>(v) : static_cast<u64>(v); }
U norm2(i64 x, i64 y) { return add(mul(absu(x), absu(x)), mul(absu(y), absu(y))); }

Pts flat_quad(Point p0, Point c, Point p1, std::int32_t tol, u32* n_out = nullptr) {
  Pts out(kMaxOutputPoints, Point{kSentinelCoord, kSentinelCoord});
  u32 cnt = 0;
  REQUIRE(flatten_quad(p0, c, p1, tol, out.data(), kMaxOutputPoints, &cnt) == Status::Ok);
  if (n_out) *n_out = cnt - 1;
  out.resize(cnt);
  return out;
}
Pts flat_cubic(Point p0, Point c0, Point c1, Point p1, std::int32_t tol, u32* n_out = nullptr) {
  Pts out(kMaxOutputPoints, Point{kSentinelCoord, kSentinelCoord});
  u32 cnt = 0;
  REQUIRE(flatten_cubic(p0, c0, c1, p1, tol, out.data(), kMaxOutputPoints, &cnt) == Status::Ok);
  if (n_out) *n_out = cnt - 1;
  out.resize(cnt);
  return out;
}

// Exact Bernstein numerators at parameter s / D (D = 8 n), common denominator D^2 (quad) or D^3 (cubic).
struct Num {
  i64 x, y;
};
Num bern_quad(const Point* p, i64 a, i64 s) {
  return Num{a * a * p[0].x + 2 * a * s * p[1].x + s * s * p[2].x, a * a * p[0].y + 2 * a * s * p[1].y + s * s * p[2].y};
}
Num bern_cubic(const Point* p, i64 a, i64 s) {
  return Num{a * a * a * p[0].x + 3 * a * a * s * p[1].x + 3 * a * s * s * p[2].x + s * s * s * p[3].x,
             a * a * a * p[0].y + 3 * a * a * s * p[1].y + 3 * a * s * s * p[2].y + s * s * s * p[3].y};
}

// Exact check of |B(t) - L(t)| at t = (8 i + r) / (8 n), against: exact polyline <= tol (exact = true) or rounded polyline
// <= tol + 3/4 (exact = false). Returns false on the first violation. cubic selects the curve.
bool deviation_ok(const Point* p, bool cubic, std::int32_t tol, const Pts& out, bool exact) {
  const i64 n = static_cast<i64>(out.size()) - 1;
  const i64 deg_den = cubic ? n * n * n : n * n;   // denominator of the exact sample numerators
  const i64 D = 8 * n;
  const i64 den = cubic ? D * D * D : D * D;       // denominator of B(t)
  for (i64 i = 0; i < n; ++i) {
    // exact samples at the segment ends, over deg_den
    const Num e0 = cubic ? bern_cubic(p, n - i, i) : bern_quad(p, n - i, i);
    const Num e1 = cubic ? bern_cubic(p, n - i - 1, i + 1) : bern_quad(p, n - i - 1, i + 1);
    for (i64 r = 0; r < 8; ++r) {
      const i64 s = 8 * i + r;
      const Num b = cubic ? bern_cubic(p, D - s, s) : bern_quad(p, D - s, s);
      i64 lx, ly;
      if (exact) {
        const i64 f = den / (8 * deg_den);  // 64 for cubic (512 n^3 / 8 n^3), 8 for quad
        lx = f * ((8 - r) * e0.x + r * e1.x);
        ly = f * ((8 - r) * e0.y + r * e1.y);
      } else {
        const i64 f = den / 8;
        lx = f * ((8 - r) * out[static_cast<std::size_t>(i)].x + r * out[static_cast<std::size_t>(i + 1)].x);
        ly = f * ((8 - r) * out[static_cast<std::size_t>(i)].y + r * out[static_cast<std::size_t>(i + 1)].y);
      }
      const U d2 = norm2(b.x - lx, b.y - ly);
      if (exact) {
        const u64 lim = static_cast<u64>(tol) * static_cast<u64>(den);
        if (!le(d2, mul(lim, lim))) return false;
      } else {
        const u64 lim = static_cast<u64>(4 * tol + 3) * static_cast<u64>(den);
        if (!le(shl4(d2), mul(lim, lim))) return false;
      }
    }
  }
  return true;
}

